class Solution {
public:
    vector<int> maxUpgrades(vector<int>& count, vector<int>& upgrade, vector<int>& sell, vector<int>& money) {
        vector<int> ans;
        for (int i = 0; i < (int)count.size(); i++) {
            long long cap = (long long)money[i] + (long long)count[i] * sell[i];
            long long den = (long long)upgrade[i] + sell[i];
            ans.push_back((int)min((long long)count[i], cap / den));
        }
        return ans;
    }
};

