class Solution:
    def maxUpgrades(self, count: List[int], upgrade: List[int], sell: List[int], money: List[int]) -> List[int]:
        ans = []
        for c, u, s, m in zip(count, upgrade, sell, money):
            lo, hi = 0, c
            while lo < hi:
                mid = (lo + hi + 1) // 2
                need = max(0, mid * u - m)
                if mid + (need + s - 1) // s <= c:
                    lo = mid
                else:
                    hi = mid - 1
            ans.append(lo)
        return ans

